import{_ as a,C as n,o,c as d,E as i,a2 as r}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Release I1.0","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Release I1.0","outline":"deep","citation":{"work":"TMPA Implementation Case","identifier":"TMPA-CASE-I1.0","language":"en","metadata":"/releases/tmpa/v1.0/metadata/implementation-case.en.cff"}},"headers":[],"relativePath":"en/publications/implementation-case-i1.0/part-01.md","filePath":"en/publications/implementation-case-i1.0/part-01.md","lastUpdated":1786439037000}'),s={name:"en/publications/implementation-case-i1.0/part-01.md"};function c(l,e,p,u,h,m){const t=n("ArticleCover");return o(),d("div",null,[i(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"An exact-input TMPA Core S1.0 product run and locked public evidence package for CodeFlowMu V1.8.0.",version:"I1.0",status:"Stable release · S1.0 product evidence · 14/14 PASS",languageHref:"/zh/publications/implementation-case-i1.0",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="tmpa-core-s1-0-fcop-codeflowmu-v1-8-0-and-retained-field-evidence" tabindex="-1">TMPA Core S1.0, FCoP, CodeFlowMu V1.8.0, and retained field evidence <a class="header-anchor" href="#tmpa-core-s1-0-fcop-codeflowmu-v1-8-0-and-retained-field-evidence" aria-label="Permalink to &quot;TMPA Core S1.0, FCoP, CodeFlowMu V1.8.0, and retained field evidence&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> I1.0<br><strong>Status:</strong> Official implementation and case report<br><strong>Normative Target:</strong> <a href="/joinwell52/en/publications/tmpa-core-specification-s1.0">TMPA Core Specification S1.0</a>, frozen candidate commit <code>942cbb097eb3d662662f96a2269818ec9d7ca2ed</code><br><strong>Product Under Test:</strong> CodeFlowMu V1.8.0, evidence commit <code>c1e1f724293e8048fc3a956b6f6df8cf83f54830</code><br><strong>Evidence Capture:</strong> 2026-08-11, Asia/Shanghai<br><strong>Formal Evidence Package:</strong> <code>tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811.zip</code><br><strong>Package SHA-256:</strong> <code>9b92b06c3e46c8019362f55075be4ed066cb7a9c0d9859945b6c3b7de8840d04</code></p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>I1.0 evaluates CodeFlowMu V1.8.0 against all fourteen mandatory criteria in TMPA Core S1.0 using the exact bytes frozen by the normative candidate commit. The CodeFlowMu product path reports <strong>14 PASS, 0 PARTIAL, 0 NOT RUN, and 0 FAIL</strong>. The runner calls <code>GovernanceReader.readSync</code>; it does not call the TMPA Reference Reader. The input-bundle digest is <code>sha256:f98764987760cdc8ac356b1265fc98485f33345e7d6ffc8575ccb059ddd34daa</code>, and the result digest is <code>sha256:0f0f642449db1853371861751a7a8ea36dce00013f53e32012a5e4dae45f4c39</code>.</p><p>The evidence package fixes the S1.0 schemas, profiles, fixtures, product Adapter and Reader source, CodeFlowMu and FCoP revisions, dependency locks, raw command logs, pre-fix failures, final regression results, a reduced clean-machine reproducer, and a 889-entry SHA-256 manifest. The final regression record contains 24/24 TMPA Runtime tests, 1,522 passed / 0 failed / 1 skipped Runtime tests, 791/791 Shell tests, and 1,210 passed / 2 skipped FCoP reference-implementation tests.</p><p>The strongest supported conclusion is <strong>author-run demonstrated product behavior for one exact implementation and one exact S1.0 bundle</strong>. The result is not independent validation, third-party certification, universal conformance, proof of TMPA theory, proof of semantic truth, proof that hallucinations have been eliminated, or independent adoption.</p><h1 id="_1-scope-and-research-questions" tabindex="-1">1. Scope and Research Questions <a class="header-anchor" href="#_1-scope-and-research-questions" aria-label="Permalink to &quot;1. Scope and Research Questions&quot;">​</a></h1><p>I1.0 asks:</p><ol><li>Does the CodeFlowMu V1.8.0 product Reader satisfy S1.0 C01–C14 against the exact frozen input bundle?</li><li>Can the source revision, product revision, input bundle, per-criterion results, regression runs, and evidence archive be traced without substituting the Reference Reader?</li><li>Does the evidence package preserve pre-fix results and demonstrate a clean reproducer without weakening the S1.0 criteria?</li><li>Which findings are demonstrated, and which conclusions remain unsupported?</li></ol><p>The unit of judgment is a criterion-bound claim over a fixed bundle. Evidence maturity and conformance verdicts are reported separately:</p><table tabindex="0"><thead><tr><th>Evidence level</th><th>Meaning in I1.0</th><th style="text-align:right;">Reached?</th></tr></thead><tbody><tr><td>Specified</td><td>S1.0 clauses, schemas, profiles, and C01–C14 define the required behavior</td><td style="text-align:right;">Yes</td></tr><tr><td>Implemented</td><td>CodeFlowMu V1.8.0 contains the corresponding Adapter, Reader, protocol, and governance mechanisms</td><td style="text-align:right;">Yes</td></tr><tr><td>Demonstrated</td><td>Author-run product and regression executions produced inspectable evidence</td><td style="text-align:right;">Yes, for the fixed bundle and revision</td></tr><tr><td>Independently Adopted</td><td>An unrelated organization adopted and independently validated the mechanism</td><td style="text-align:right;">No</td></tr></tbody></table><h1 id="_2-architecture-and-evidence-boundaries" tabindex="-1">2. Architecture and Evidence Boundaries <a class="header-anchor" href="#_2-architecture-and-evidence-boundaries" aria-label="Permalink to &quot;2. Architecture and Evidence Boundaries&quot;">​</a></h1><p>The current guidance and implementation relation is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper A1.0</span></span>
<span class="line"><span>        ↓ provides the architecture theory and design direction</span></span>
<span class="line"><span>TMPA Core Specification S1.0</span></span>
<span class="line"><span>        ↓ fixes normative object, Reader, and conformance behavior</span></span>
<span class="line"><span>FCoP protocol</span></span>
<span class="line"><span>        ↓ supplies the file-based coordination and evidence profile</span></span>
<span class="line"><span>CodeFlowMu V1.8.0</span></span>
<span class="line"><span>        ↓ implements and consumes the Adapter/Reader result</span></span>
<span class="line"><span>bounded cases, governance gates, recovery, and audit views</span></span></code></pre></div><p>TMPA is the theory and normative governance layer. FCoP is a reusable coordination protocol, not an application program. The <code>fcop</code> and <code>fcop-mcp</code> packages are reference implementations of FCoP rather than the protocol itself. CodeFlowMu is the engineering system guided by TMPA: it emits and consumes coordination evidence, projects FCoP artifacts into TMPA candidates, reconstructs a governance view, and lets workflow, review, recovery, and audit components consume the result.</p><p>Historical co-evolution is reported separately. XiaoDian AI, FCoP, CodeFlowMu, and TMPA share an author-controlled lineage; engineering feedback helped refine the present formalization. That lineage does not make an implementation a proof of the theory. WP-13 remains a bounded example of role-separated evidence admission and fact checking; it does not prove hallucination elimination and is not substituted for the S1.0 C01–C14 run.</p><h1 id="_3-fixed-sources-and-evidence-design" tabindex="-1">3. Fixed Sources and Evidence Design <a class="header-anchor" href="#_3-fixed-sources-and-evidence-design" aria-label="Permalink to &quot;3. Fixed Sources and Evidence Design&quot;">​</a></h1><h2 id="_3-1-locked-identities" tabindex="-1">3.1 Locked identities <a class="header-anchor" href="#_3-1-locked-identities" aria-label="Permalink to &quot;3.1 Locked identities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Fixed identity</th><th>Role in this report</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S1.0 candidate commit <code>942cbb097eb3d662662f96a2269818ec9d7ca2ed</code></td><td>Normative input</td></tr><tr><td>CodeFlowMu</td><td>V1.8.0 evidence commit <code>c1e1f724293e8048fc3a956b6f6df8cf83f54830</code></td><td>Product under test</td></tr><tr><td>CodeFlowMu protocol surface</td><td>V1.2.0</td><td>Product schema and validator surface</td></tr><tr><td>FCoP reference implementation</td><td>commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code></td><td>Locked dependency regression only</td></tr><tr><td>Product Reader</td><td><code>GovernanceReader.readSync</code></td><td>Required execution path</td></tr><tr><td>Product Adapter</td><td><code>FcopSourceAdapter.projectFcopToTmpa</code></td><td>FCoP-to-TMPA projection path</td></tr></tbody></table><p>The product run used an isolated, tracked-clean evidence worktree. The original CodeFlowMu mother worktree was observed as dirty and changing, so it was not used as the evidentiary execution root. The V1.8.0 evidence commit was local-only at capture time: it was not pushed, tagged, or released. The complete source snapshot and V1.7.0-to-V1.8.0 patch are therefore included in the evidence archive. This supports inspection of the tested source but does not turn the commit into a public CodeFlowMu release.</p><h2 id="_3-2-fixed-machine-inputs" tabindex="-1">3.2 Fixed machine inputs <a class="header-anchor" href="#_3-2-fixed-machine-inputs" aria-label="Permalink to &quot;3.2 Fixed machine inputs&quot;">​</a></h2><p>The run locks four S1.0 JSON Schemas plus the lifecycle Profile, canonicalization Profile, fixtures, and input bundle identity. The four published Schema hashes are:</p><table tabindex="0"><thead><tr><th>Schema</th><th>SHA-256</th></tr></thead><tbody><tr><td>Governance object</td><td><code>a2829cd7149c3054a52886365f2293a23106b636b0c52799739bfabdab1ff4fa</code></td></tr><tr><td>Lifecycle Profile</td><td><code>481a61ac2485bbaf15d90e9c5a255ad9ce6a55971190f0fe404856be4b10f993</code></td></tr><tr><td>Reader result</td><td><code>4527df7096fe840b85b245e50d5cea576ff359d50a54d17c8873a7b4f458d431</code></td></tr><tr><td>Conformance result</td><td><code>4b1ecebf83e62d2aa1aff0e79a0cd0ea0a85fbc14a426d5fe873ab40aefdc2fe</code></td></tr></tbody></table><h2 id="_3-3-evidence-construction" tabindex="-1">3.3 Evidence construction <a class="header-anchor" href="#_3-3-evidence-construction" aria-label="Permalink to &quot;3.3 Evidence construction&quot;">​</a></h2><p>For each criterion, the product runner records a manifest, explicit mandatory assertions, product input invocations, canonical Reader output, assertion outcomes, a manifest digest, and a result digest. The aggregate result is validated against the S1.0 conformance-result Schema. Raw stdout, stderr, exit status, command, working directory, environment, dependency-lock digest, and remediation history are retained.</p><p>The frozen S1.0 candidate corpus also contains a historical product <code>NOT RUN</code> baseline. I1.0 does not rewrite it. The V1.8.0 product result is registered as a later external exact-version run so that candidate history and later evidence remain distinguishable.</p>`,27))])}const g=a(s,[["render",c]]);export{b as __pageData,g as default};
